parameters.jsCode:
const run = $input.first().json;
const steps = run.intermediateSteps || [];

const clean = value => {
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  try {
    const parsed = JSON.parse(text);
    const first = Array.isArray(parsed) ? parsed[0] : parsed;
    return first.output ?? first.response ?? first.text ?? text;
  } catch {
    return text;
  }
};

const resultOf = word => {
  const step = steps.filter(s => String(s.action?.tool || '').toLowerCase().includes(word)).pop();
  return step ? clean(step.observation) : null;
};

const sections = [
  ['Match Analysis', resultOf('matcher'), 'CV Matcher'],
  ['Tailored Cover Letter', resultOf('letter'), 'Cover Letter Writer'],
  ['Interview Preparation', resultOf('interview'), 'Interview Coach'],
];

const report = [run.output]
  .concat(sections.map(([title, body, agent]) => '## ' + title + '\n\n' + (body || '_The ' + agent + ' did not run this time. Please submit the form again._')))
  .join('\n\n');

return [{ json: { report, specialistsUsed: sections.filter(s => s[1]).length } }];

